const messageLine=(message)=>message.type==='notice'?`<article class="host-notice"><b>主播公告</b><strong>月满中秋，群雄再战！</strong><p>VIP群各路大神云集，<br>实战经验赛事观点火热分享，<br>私聊主播立即领取</p></article>`:`<p class="chat-line ${message.host?'host-line':''}"><span class="vip-chip">${message.vip}</span><span class="badge-chip">${message.badge}</span>${message.host?'<span class="host-chip">主播</span>':''}<b>${message.name}</b><span>：${message.text}</span></p>`;
function playerControls(){return `<div class="player-controls"><div class="player-controls-left"><button data-player="play" aria-label="${playerPlaying?'暂停':'播放'}">${playerPlaying?'Ⅱ':'▶'}</button><button data-player="mute" aria-label="${playerMuted?'开启声音':'静音'}">${playerMuted?'🔇':'🔊'}</button><input data-player-volume type="range" min="0" max="100" value="${playerMuted?0:68}" aria-label="音量"></div><div class="player-controls-right"><button data-player="danmaku" class="${danmakuOn?'on':''}">弹幕</button><div class="quality-wrap"><button data-player="quality">${quality} ▾</button>${qualityOpen?`<div class="quality-menu"><button data-quality="超清" class="${quality==='超清'?'selected':''}">超清</button><button data-quality="标清" class="${quality==='标清'?'selected':''}">标清</button></div>`:''}</div><button data-player="fullscreen">⛶</button></div></div>`}
function giftSection(){let perPage=8,start=giftPage*perPage,visible=gifts.slice(start,start+perPage),maxPage=Math.ceil(gifts.length/perPage)-1;return `<section class="room-gifts"><div class="gift-row"><div class="gift-carousel"><button class="gift-page-btn" data-gift-page="prev" ${giftPage===0?'disabled':''} aria-label="上一页礼物">‹</button><div class="gift-list">${visible.map(gift=>`<div class="gift-item"><img src="${gift.cover}" alt="${gift.name}"><div class="gift-pop"><img src="${gift.cover}" alt=""><b>${gift.name}</b><p>${gift.description}</p><strong>${gift.price}</strong><button data-gift-send="${gift.id}">赠送</button></div></div>`).join('')}</div><button class="gift-page-btn" data-gift-page="next" ${giftPage===maxPage?'disabled':''} aria-label="下一页礼物">›</button></div><div class="asset-pills"><span class="asset-tile diamond"><i>◆</i><b>2,680</b><small>钻石</small></span><span class="asset-tile coin"><i>●</i><b>8,420</b><small>金币</small></span><button class="asset-action" data-action="recharge"><i>＋</i><span>充值</span></button><button class="asset-action" data-action="bag"><i>▣</i><span>背包</span></button><button class="asset-action" data-action="noble"><i>♛</i><span>贵族</span></button></div></div></section>`}
function roomChat(room){let messages=chatMessages.map(messageLine).join('');return `<div class="chat-content"><div class="chat-scroll" id="chatScroll">${entryVisible?'<div class="entry-toast">欢迎 小宇同学 进入直播间</div>':''}${messages}</div><form class="chat-input" id="roomChatForm"><input id="roomChatInput" maxlength="80" placeholder="说点什么吧..." autocomplete="off"><button type="button" class="gift-trigger" data-open-gifts>🎁 礼物</button><button type="submit">发送</button></form></div>`}
function groupList(){return `<div class="group-list">${groups.map(group=>`<button class="group-item" data-group="${group.id}"><span class="group-avatar" style="--group:${group.color}">${group.title.slice(0,2)}</span><span class="group-copy"><b>${group.title}</b><small>${group.last}</small></span><span class="group-meta"><time>${group.time}</time>${group.unread?`<i>${group.unread}</i>`:''}</span></button>`).join('')}</div>`}
function groupDetail(group){let messages=(groupMessages[group.id]||[]).map(messageLine).join('');return `<div class="group-detail"><header class="group-detail-head"><button data-back-group aria-label="返回群聊">‹</button><span class="group-avatar" style="--group:${group.color}">${group.title.slice(0,2)}</span><span><b>${group.title}</b><small>${group.people}</small></span></header><div class="chat-scroll" id="groupScroll">${messages}</div><form class="chat-input" id="groupChatForm"><input id="groupChatInput" maxlength="80" placeholder="发送群消息" autocomplete="off"><button type="submit">发送</button></form></div>`}
function roomSidebar(room){let group=groups.find(item=>item.id===selectedGroupId);return `<aside class="room-sidebar"><div class="room-side-tabs"><button class="${roomSideTab==='chat'?'selected':''}" data-side-tab="chat">聊天室</button><button class="${roomSideTab==='groups'?'selected':''}" data-side-tab="groups">群聊</button></div>${roomSideTab==='chat'?roomChat(room):(group?groupDetail(group):groupList())}</aside>`}
function roomPage(id){let room=roomOf(id),hostRecord=hostDirectory.find(item=>item.name===room.host),followId=hostRecord?.id||room.host,following=followedHosts.has(followId),recommended=liveStreams.filter(item=>item.id!==room.id).slice(0,8);return `${header()}<main class="room-page"><div class="room-layout"><div class="room-main"><section class="room-host"><img src="${room.avatar}" alt="${room.host}"><div class="room-host-copy"><h1>${room.title}</h1><p><span class="level-pill">Lv. ${room.presenterTag==='金牌主播'?36:24}</span><b>${room.host}</b><em>ID：${room.id}</em><span>🔥 ${room.heat}</span></p></div><div class="room-host-actions"><button class="share-btn" data-share>↗ 分享</button><button class="follow-btn ${following?'following':''}" data-follow-btn data-follow-host="${followId}">${following?'已关注':'+ 关注'} <small>${fanText(hostRecord?.fans||roomFans)}粉丝</small></button></div></section><section class="room-player ${playerPlaying?'is-playing':'is-paused'}"><img src="${room.cover}" alt="${room.title}"><div class="room-player-shade"></div>${danmakuOn?'<div class="danmaku d1">这波防守漂亮！</div><div class="danmaku d2">主播讲得好清楚</div><div class="danmaku d3">阿森纳加油！</div>':''}<div class="room-player-center">${playerPlaying?'':'▶'}</div>${playerControls()}</section>${giftSection()}<section class="room-recommend"><div class="section-head"><h2>推荐直播</h2><a href="#/live">更多 <b>›</b></a></div><div class="live-page-grid room-recommend-grid">${recommended.map(liveCard).join('')}</div></section></div>${roomSidebar(room)}</div></main><div class="app-toast" id="appToast" role="status"></div>${footer()}`}
function showToast(text){let toast=document.querySelector('#appToast');if(!toast)return;toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),1800)}
const eventTeam = (label, color) => `<span class="event-team-logo" style="--team-color:${color}">${label}</span>`;
function eventCard(event){ return `<a class="event-card" href="#/match/${event.id}" aria-label="查看${event.home}对${event.away}的赛事详情"><div class="event-card-top"><span class="event-league">${event.league}</span><time>${event.time}</time></div><div class="event-sides"><span class="event-team">${eventTeam(event.homeLogo,event.color)}<b>${event.home}</b></span><strong class="event-score">${event.score}</strong><span class="event-team away"><b>${event.away}</b>${eventTeam(event.awayLogo,event.color)}</span></div></a>` }
function liveGrid(category=liveCategory){ let list=category==='全部'?liveStreams:liveStreams.filter(item=>item.category===category); return list.map(liveCard).join(''); }
function popularEvents(sectionClass='live-section event-section'){return `<section class="${sectionClass}"><div class="section-head"><h2>热门赛事</h2></div><div class="event-layout"><div class="event-scroll" aria-label="热门赛事列表">${featuredEvents.map(eventCard).join('')}</div><a class="schedule-portal" href="#/schedule" aria-label="进入直播预告页"><span>直播预告</span><small>查看全部赛事</small><b>→</b></a></div></section>`}
function livePage(){ return `${header()}<main class="live-page">${popularEvents()}<section class="live-section live-feed-section"><div class="section-head"><h2>正在直播</h2></div><div class="live-category-tabs" role="tablist" aria-label="直播频道分类">${liveCategories.map(category=>`<button class="${category===liveCategory?'selected':''}" data-live-category="${category}" role="tab" aria-selected="${category===liveCategory}">${category}</button>`).join('')}</div><div class="live-page-grid" id="liveGrid">${liveGrid()}</div></section></main>${footer()}` }


