function scheduleHosts(hosts){return `<div class="schedule-hosts" aria-label="已预约主播">${hosts.slice(0,4).map((host,index)=>`<img src="https://i.pravatar.cc/80?img=${host}" alt="预约主播 ${index+1}" loading="lazy">`).join('')}</div>`}
function scheduleCard(event){let live=event.status==='live',content=`<div class="schedule-card-top"><span class="schedule-sport ${event.sport}">${scheduleSportLabels[event.sport]}</span><span class="schedule-league">${event.league}</span><time>${event.time}</time><span class="schedule-status ${live?'is-live':''}">${live?'<i></i>进行中':'未开赛'}</span></div><div class="schedule-card-main"><div class="schedule-team home">${scheduleLogo(event.homeLogo,event.color)}<b>${event.home}</b></div><div class="schedule-score"><strong>${live?event.score:'VS'}</strong><small>${live?event.stage:'等待开赛'}</small></div><div class="schedule-team away"><b>${event.away}</b>${scheduleLogo(event.awayLogo,event.color)}</div></div><div class="schedule-card-foot"><span>${live?'正在直播':'计划直播'} · ${event.hosts.length} 位主播</span>${scheduleHosts(event.hosts)}<span class="${live?'schedule-watch':'schedule-upcoming'}">${live?'进入直播间 →':'敬请期待'}</span></div>`;return live?`<a class="schedule-card live" href="#/room/${event.roomId}" aria-label="进入${event.home}对${event.away}的直播间">${content}</a>`:`<article class="schedule-card upcoming" aria-label="${event.home}对${event.away}，尚未开赛">${content}</article>`}
function schedulePage(){let dayEvents=scheduleEvents.filter(event=>event.date===scheduleDay),available=['football','basketball','other'].filter(sport=>dayEvents.some(event=>event.sport===sport));if(!available.includes(scheduleSport))scheduleSport=available[0];let events=dayEvents.filter(event=>event.sport===scheduleSport);return `${header()}<main class="schedule-page"><section class="schedule-panel" aria-label="赛事预告筛选"><div class="schedule-days" role="tablist" aria-label="日期选择">${scheduleDays.filter(day=>scheduleEvents.some(event=>event.date===day.id)).map(day=>`<button class="${scheduleDay===day.id?'selected':''}" data-schedule-day="${day.id}" role="tab" aria-selected="${scheduleDay===day.id}"><b>${day.label}</b><span>(${scheduleEvents.filter(event=>event.date===day.id).length})</span></button>`).join('')}</div><div class="schedule-sport-tabs" role="tablist" aria-label="体育类型选择">${available.map(sport=>`<button class="${scheduleSport===sport?'selected':''}" data-schedule-sport="${sport}" role="tab" aria-selected="${scheduleSport===sport}">${scheduleSportLabels[sport]}</button>`).join('')}</div></section><section class="schedule-list"><div class="schedule-list-head"><div><h2>${scheduleDays.find(day=>day.id===scheduleDay).label} · ${scheduleSportLabels[scheduleSport]}</h2><p>共 ${events.length} 场赛事</p></div></div><div class="schedule-grid">${events.map(scheduleCard).join('')}</div></section></main>${footer()}`}


