function fixtureExtra(i,football,status){let cards=football&&i%4===0?{home:{yellow:(i%3)+1,red:i%8===0?1:0},away:{yellow:i%5===0?2:0,red:i%11===0?1:0}}:undefined; if(cards){for(let side of ['home','away'])if(cards[side]&&!cards[side].yellow&&!cards[side].red)delete cards[side]}return {hosts:i%6===0?[]:Array.from({length:(i%5)+1},(_,x)=>((i*7+x*9)%66)+1),video:i%6===0&&i%2===0,cards,half:football&&status!=='upcoming'&&i%3!==1?`${i%3} : ${(i+1)%3}`:undefined,corners:football&&i%4!==1?`${i%8} : ${(i+3)%8}`:undefined,color:['#d9544d','#5577d5','#3a8dd5','#9b65c4','#e09b31'][i%5]}}
