const matchSportLabel={recommend:'推荐',football:'足球',basketball:'篮球',nba:'NBA'},matchType=e=>e.league==='NBA'?'nba':e.sport;
function filteredMatches(){let status={live:'live',schedule:'upcoming',results:'finished'}[matchTab];return matchEvents.filter(e=>(!status||e.status===status)&&(!status||matchTab!=='schedule'||e.date===matchScheduleDate)&&(!status||matchTab!=='results'||e.date===matchResultDate)&&(matchTab!=='favorites'||followedMatches.has(e.id))&&(matchSport==='recommend'||matchType(e)===matchSport)&&(!matchLeagues.size||matchLeagues.has(e.league)))}
function matchDates(results){return Array.from({length:7},(_,i)=>{let n=results?i-6:i,d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+n);return {key:d.toISOString().slice(0,10),label:n===0?'今天':n===1?'明天':'周'+['日','一','二','三','四','五','六'][d.getDay()],date:String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')}})}
const matchLogo=(name,color)=>`<span class="match-team-logo" style="--match-color:${color||'#64748b'}">${initials(name)}</span>`;
function matchHosts(hosts=[]){return `<div class="match-hosts">${hosts.slice(0,3).map((x,i)=>`<img src="https://i.pravatar.cc/80?img=${x}" alt="预约主播 ${i+1}">`).join('')}${hosts.length>3?`<span>+${hosts.length-3}</span>`:''}</div>`}
function matchCards(cards={},side){let x=cards[side]||{};return `<span class="match-cards">${x.yellow?`<i class="yellow">${x.yellow}</i>`:''}${x.red?`<i class="red">${x.red}</i>`:''}</span>`}
function matchCard(e){let favorited=followedMatches.has(e.id),live=e.status==='live',state=live?e.stage:e.status==='upcoming'?'未':'完',stats=[e.half?`半场 ${e.half}`:'',e.corners?`角球 ${e.corners}`:''].filter(Boolean),streamSlot=e.hosts?.length?matchHosts(e.hosts):(e.video?`<i class="match-video-source" title="有视频直播源" aria-label="有视频直播源">▶</i>`:'');return `<a class="match-card match-card-line" href="#/match/${e.id}"><div class="match-line-event"><span class="match-sport ${e.sport}">${e.sport==='football'?'⚽ 足球':'🏀 篮球'}</span><span class="match-line-league">${e.league}</span><time class="match-line-time">${e.time}</time><span class="match-state ${live?'live':''}">${live?'<i></i>':''}${state}</span></div><div class="match-line-game"><div class="match-line-team home">${matchCards(e.cards,'home')}<b title="${e.home}">${e.home}</b>${matchLogo(e.home,e.color)}</div><strong class="match-line-score">${e.score||'VS'}</strong><div class="match-line-team away">${matchLogo(e.away,e.color)}<b title="${e.away}">${e.away}</b>${matchCards(e.cards,'away')}</div></div><span class="match-line-stats">${stats.map(stat=>`<i>${stat}</i>`).join('')}</span><span class="match-line-hosts">${streamSlot}</span><button class="match-star ${favorited?'saved':''}" data-match-follow="${e.id}" aria-label="${favorited?'取消收藏':'收藏赛事'}">${favorited?'★':'☆'}</button></a>`}

const matchLeagueLetter={CBA:'C',EuroLeague:'E',NBL:'N',NBA:'N','德甲':'D','法甲':'F','欧冠':'O','西甲':'X','意甲':'Y','英超':'Y'};
function draftMatchCount(){let status={live:'live',schedule:'upcoming',results:'finished'}[matchTab];return matchEvents.filter(e=>(!status||e.status===status)&&(!status||matchTab!=='schedule'||e.date===matchScheduleDate)&&(!status||matchTab!=='results'||e.date===matchResultDate)&&(matchTab!=='favorites'||followedMatches.has(e.id))&&(matchSport==='recommend'||matchType(e)===matchSport)&&(!matchDraftLeagues.size||matchDraftLeagues.has(e.league))).length}
function refreshMatchDraftUI(){let count=draftMatchCount();document.querySelectorAll('[data-match-league]').forEach(button=>button.classList.toggle('selected',matchDraftLeagues.has(button.dataset.matchLeague)));document.querySelectorAll('[data-match-reset]').forEach(button=>button.classList.toggle('selected',!matchDraftLeagues.size));let summary=document.querySelector('[data-match-draft-summary]');if(summary)summary.innerHTML=`已选 <b>${matchDraftLeagues.size}</b> 个联赛 · <b>${count}</b> 场赛事`}
function matchFilterPanel(){let leagues=[...new Set(matchEvents.filter(e=>matchSport==='recommend'||matchType(e)===matchSport).map(e=>e.league))].sort((a,b)=>a.localeCompare(b,'zh-CN')),selectedEvents=draftMatchCount();return !matchFilterOpen?'':`<aside class="match-filter-popover" aria-label="联赛筛选"><header><b>${matchSportLabel[matchSport]} · 联赛筛选</b><button data-match-filter-close aria-label="关闭筛选">×</button></header><div class="popover-leagues"><button class="league-tile ${!matchDraftLeagues.size?'selected':''}" data-match-reset><b>全部联赛</b><small>显示全部赛事</small><i>✓</i></button>${leagues.map(league=>{let count=matchEvents.filter(e=>e.league===league&&(matchSport==='recommend'||matchType(e)===matchSport)).length;return `<button class="league-tile ${matchDraftLeagues.has(league)?'selected':''}" data-match-league="${league}"><b>${league}</b><small>${count} 场赛事</small><i>✓</i></button>`}).join('')}</div><footer><span data-match-draft-summary>已选 <b>${matchDraftLeagues.size}</b> 个联赛 · <b>${selectedEvents}</b> 场赛事</span><div><button data-match-select="all">全选</button><button data-match-select="invert">反选</button><button data-match-reset>重置</button><button class="popover-confirm" data-match-confirm>确定</button></div></footer></aside>`}

function matchesPage(){let events=filteredMatches(),dates=matchTab==='schedule'?matchDates(false):matchTab==='results'?matchDates(true):null,chosen=matchTab==='schedule'?matchScheduleDate:matchResultDate,empty=matchTab==='favorites'?'暂未收藏赛事':'暂无赛事';return `${header()}<main class="matches-page"><section class="matches-panel"><div class="match-primary">${Object.keys(matchSportLabel).map(x=>`<button class="${matchSport===x?'selected':''}" data-match-sport="${x}">${matchSportLabel[x]}</button>`).join('')}</div><div class="match-secondary"><div>${[['live','即时'],['schedule','赛程'],['results','赛果'],['favorites','收藏']].map(([x,n])=>`<button class="${matchTab===x?'selected':''}" data-match-tab="${x}">${n}</button>`).join('')}</div><button class="match-filter-trigger" data-match-filter>筛选${matchLeagues.size?` <em>${matchLeagues.size}</em>`:''}</button></div>${matchFilterPanel()}</section>${dates?`<div class="match-date-strip">${dates.map(d=>`<button class="${chosen===d.key?'selected':''}" data-match-date="${d.key}"><b>${d.label}</b><span>${d.date}</span></button>`).join('')}</div>`:''}<section class="match-list"><div class="match-grid">${events.length?events.map(matchCard).join(''):`<div class="match-empty"><span>◌</span><b>${empty}</b><small>${matchTab==='favorites'?'关注感兴趣的赛事后，会显示在这里。':'换个日期或筛选条件看看吧。'}</small></div>`}</div></section></main>${footer()}`}

function featuredEventDetail(id){let event=featuredEvents.find(item=>item.id===id);if(!event)return null;let sport=event.league.includes('NBA')||event.league==='CBA'?'basketball':event.league==='英超'?'football':'other',sportLabel=sport==='basketball'?'篮球':sport==='football'?'足球':event.league.includes('ATP')?'网球':event.league.includes('英雄联盟')?'英雄联盟':'王者荣耀';return {...event,sport,sportLabel,status:event.score==='VS'?'upcoming':'live',stage:event.score==='VS'?'等待开赛':'进行中',hosts:[]}}
function matchDetailPage(id){let e=matchEvents.find(x=>x.id===id)||featuredEventDetail(id);if(!e)return simplePage('赛事不存在','该赛事可能已下线或暂未开放。');let following=followedMatches.has(id);return `${header()}<main class="match-detail-page"><a class="match-back" href="#/matches">‹ 返回赛事中心</a><section class="match-detail-card"><div class="match-card-top"><span class="match-sport ${e.sport}">${e.sportLabel|| (e.sport==='football'?'⚽ 足球':'🏀 篮球')}</span><b>${e.league}</b><time>${e.time}</time><span class="match-state ${e.status==='live'?'live':''}">${e.status==='live'?e.stage:e.status==='finished'?'已结束':'未开赛'}</span></div><div class="match-detail-score"><div>${matchLogo(e.home,e.color)}<b>${e.home}</b></div><strong>${e.score||'VS'}</strong><div>${matchLogo(e.away,e.color)}<b>${e.away}</b></div></div><div class="match-detail-info">${e.half?`半场比分 ${e.half}`:''}${e.corners?`<span>⚑ 角球 ${e.corners}</span>`:''}${e.hosts?.length?`<span>已有 ${e.hosts.length} 位主播预约直播</span>`:''}</div><button class="match-follow ${following?'following':''}" data-match-follow="${e.id}">${following?'已关注':'＋ 关注赛事'}</button></section></main>${footer()}`}

