const followedHosts=new Set();
const searchKeyword=()=>{let hash=location.hash||'';return (new URLSearchParams(hash.includes('?')?hash.split('?')[1]:'')).get('keyword')?.trim()||''};
const searchStreams=()=>[...liveRooms,...hotRooms,...liveStreams,...searchExtraStreams].filter((item,index,all)=>all.findIndex(other=>other.id===item.id)===index);
const escapeHTML=(value='')=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const fanCount=(count)=>count>=10000?`${(count/10000).toFixed(1).replace('.0','')}万`:`${count}`;
function searchHostCard(host){let following=followedHosts.has(host.id),target=host.liveRoom?`直播中`:`未开播`;return `<article class="search-host-card" data-host-open="${host.id}" role="link" tabindex="0" aria-label="查看主播 ${host.name}"><div class="search-host-avatar ${host.liveRoom?'is-live':''}"><img src="${host.avatar}" alt="${host.name}"><i></i></div><b>${host.name}</b><small>${fanCount(host.fans)} 粉丝</small><span class="host-status ${host.liveRoom?'live':''}">${host.liveRoom?'正在直播':'暂未开播'}</span><button class="follow-btn ${following?'following':''}" data-host-follow="${host.id}">${following?'已关注':'+ 关注'}</button></article>`}
function profilePage(id){let host=hostDirectory.find(item=>item.id===id);return `${header()}<main class="subpage"><div class="subpage-card"><span class="page-eyebrow">主播个人中心</span><h1>${host?host.name:'主播'}</h1><p>${host?`${fanCount(host.fans)} 粉丝 · 当前${host.liveRoom?'正在直播':'暂未开播'}`:'该主播信息暂未开放。'}</p>${host?.liveRoom?`<a class="go-live" href="#/room/${host.liveRoom}">进入直播间</a>`:'<a class="go-live" href="#/live">浏览直播</a>'}</div></main>${footer()}`}
function searchPage(){let keyword=searchKeyword(),needle=keyword.toLocaleLowerCase(),streams=needle?searchStreams().filter(item=>[item.title,item.category,item.league,item.host,item.presenterTag].filter(Boolean).join(' ').toLocaleLowerCase().includes(needle)):[],hosts=needle?hostDirectory.filter(host=>host.name.toLocaleLowerCase().includes(needle)):[],resultCount=streams.length+hosts.length;let content=!streams.length&&!hosts.length?`<section class="search-empty"><div>⌕</div><h1>未找到相关内容</h1><p>换个关键词试试吧</p></section>`:`${streams.length?`<section class="search-section"><div class="search-section-head"><h2>直播</h2><span>找到 ${streams.length} 个相关直播</span></div><div class="search-live-grid">${streams.map(liveCard).join('')}</div></section>`:''}${hosts.length?`<section class="search-section search-host-section"><div class="search-section-head"><h2>主播</h2><span>找到 ${hosts.length} 位相关主播</span></div><div class="search-host-grid">${hosts.map(searchHostCard).join('')}</div></section>`:''}`;return `${header()}<main class="search-page"><div class="search-page-title"><p>搜索结果</p><h1>“${escapeHTML(keyword)}”</h1><div class="search-result-summary">共找到相关结果 <b>${resultCount}</b> 个</div></div>${content}</main>${footer()}`}

function downloadPanel(){return `<section class="download-panel" aria-label="神马直播 App 下载"><div class="download-brand"><span class="brand-mark">S</span><b>神马直播</b></div><img class="download-qr" src="${downloadQrUrl}" alt="神马直播 App 下载二维码"><small>扫码下载 App，随时看精彩赛事</small><button class="download-now" type="button" data-action="app-download">立即下载</button></section>`}
function floatingDownload(){return `<div class="floating-download"><button class="floating-download-button" type="button" aria-haspopup="dialog"><i>${icon('download')}</i><span>下载 App</span></button>${downloadPanel()}</div>`}

function header(){ const route=location.hash||'#/'; return `<header class="site-header"><div class="header-inner"><a class="brand" href="#/" aria-label="神马直播 首页"><span class="brand-mark">S</span><span>神马直播</span></a><nav class="main-nav">${navs.map(([n,h])=>`<a href="${h}" class="${route===h||(h==='#/live'&&route.startsWith('#/room/'))?'active':''}">${n}</a>`).join('')}</nav><form class="search" id="searchForm"><button class="search-submit" type="submit" aria-label="搜索">${icon('search')}</button><input id="searchInput" value="${escapeHTML(searchKeyword())}" placeholder="请输入搜索内容" autocomplete="off"></form><div class="header-actions"><button class="utility" data-action="game"><i>${icon('game')}</i>游戏</button><div class="download-entry"><button class="utility download-trigger" type="button" aria-haspopup="dialog"><i>${icon('download')}</i>下载 App</button>${downloadPanel()}</div><button class="go-live" data-action="cast">${icon('cast')} 开播</button><button class="avatar-btn" id="avatarBtn"><img src="https://i.pravatar.cc/100?img=49" alt="当前用户头像"><span class="online-dot"></span></button><div class="user-menu" id="userMenu"><b>晚上好，神马直播用户</b><a href="#/profile">个人中心</a><a href="#/creator">创作中心</a><button data-action="logout">退出登录</button></div></div></div></header>`; }
function sectionHead(title, href='#/live'){return `<div class="section-head"><h2>${title}</h2><a href="${href}">更多 <b>${icon('more')}</b></a></div>`}
function liveCard(r){return `<a class="live-card" href="#/room/${r.id}" aria-label="进入直播间：${r.title}"><div class="cover"><img src="${r.cover}" alt="" aria-hidden="true" loading="lazy" onerror="this.style.visibility='hidden'"><span class="tag" style="--tag:${r.color}">${r.presenterTag}</span><span class="card-play">${icon('play')}</span></div><div class="card-copy"><h3>${r.title}</h3><div class="host-row"><img src="${r.avatar}" alt="${r.host}"><span>${r.host}</span><em>${icon('fire')} ${r.heat}</em></div></div></a>`}
function featured(){ let r=liveRooms[activeLive]; return `<section class="featured"><div class="stage"><img src="${r.cover}" alt="${r.title}"><div class="stage-shade"></div><div class="live-pill"><i></i> 正在直播</div><button class="stage-play" aria-label="播放直播">${icon('play')}</button><div class="stage-meta"><img src="${r.avatar}" alt="${r.host}"><span><b>${r.host}</b><small>${icon('fire')} ${r.heat} 人正在观看</small></span><a href="#/room/${r.id}">进入直播间 ${icon('arrow')}</a></div></div><div class="channel-list" aria-label="直播间切换">${liveRooms.map((x,i)=>`<button class="channel ${i===activeLive?'selected':''}" data-channel="${i}" aria-label="切换至${x.title}"><img src="${x.cover}" alt="${x.title}"></button>`).join('')}</div></section>`}
function footballTable(){let data=standings.football[footballLeague]; return `<div class="rank-card football-rank"><div class="rank-tabs">${Object.keys(standings.football).map(x=>`<button class="${x===footballLeague?'selected':''}" data-football="${x}">${x}</button>`).join('')}</div><div class="rank-title"><span>足球球队排行</span><small>${footballLeague} · 2023/24</small></div><div class="rank-table football-table"><div class="rank-row table-head"><span class="team-column-head">球队</span><span aria-hidden="true"></span><span>赛</span><span>胜</span><span>平</span><span>负</span><span>进/失</span><span>积分</span></div>${data.map((t,i)=>`<a href="#/team/${encodeURIComponent(t[1])}" class="rank-row"><span class="rank-num n${i+1}">${i+1}</span><span class="team">${teamMark(t[0],t[1])}<b>${teamName(t[0],t[1])}</b></span><span>${t[2]}</span><span>${t[3]}</span><span>${t[4]}</span><span>${t[5]}</span><span>${t[6]}</span><strong>${t[7]}</strong></a>`).join('')}</div></div>`}
function basketballTable(){ let list=basketballLeague==='NBA'?standings.basketball.NBA[nbaConference]:standings.basketball.CBA.all; return `<div class="rank-card basketball-rank"><div class="rank-tabs"><button class="${basketballLeague==='NBA'?'selected':''}" data-basketball="NBA">NBA</button><button class="${basketballLeague==='CBA'?'selected':''}" data-basketball="CBA">CBA</button></div><div class="rank-title"><span>篮球球队排行</span>${basketballLeague==='NBA'?`<div class="conference"><button class="${nbaConference==='east'?'on':''}" data-conf="east">东部</button><button class="${nbaConference==='west'?'on':''}" data-conf="west">西部</button></div>`:'<small>常规赛</small>'}</div><div class="rank-table basketball-table"><div class="rank-row table-head"><span class="team-column-head">球队</span><span aria-hidden="true"></span><span>胜</span><span>负</span><span>胜率</span><span>胜差</span><span>近况</span></div>${list.map((t,i)=>`<a href="#/team/${encodeURIComponent(t[1])}" class="rank-row"><span class="rank-num n${i+1}">${i+1}</span><span class="team">${teamMark(t[0],t[1])}<b>${teamName(t[0],t[1])}</b></span><span>${t[2]}</span><span>${t[3]}</span><span>${winRate(t[4])}</span><span>${t[5]}</span><span class="form">${t[6]}</span></a>`).join('')}</div></div>`}
function footer(){return `<footer><div class="footer-inner"><div class="footer-brand"><span class="brand-mark">S</span><b>神马直播</b><p>与你一起，见证每一场热爱。</p></div><div class="footer-links"><span>平台服务</span><span>帮助中心</span><span>商务合作</span><span>用户协议</span><span>隐私政策</span></div><div class="copyright">© 2026 神马直播. All rights reserved.</div></div></footer>`}
function home(){return `${header()}<main><div class="featured-wrap">${featured()}</div>${popularEvents('content-section home-events event-section')}<section class="content-section hot">${sectionHead('热门直播')}<div class="live-grid">${hotRooms.map(liveCard).join('')}</div></section><section class="content-section standings">${sectionHead('球队排行','#/matches')}<div class="ranking-grid">${footballTable()}${basketballTable()}</div></section></main>${floatingDownload()}${footer()}`}
function simplePage(kind, text){return `${header()}<main class="subpage"><div class="subpage-card"><span class="page-eyebrow">SMLIVE WEB</span><h1>${kind}</h1><p>${text}</p><a class="go-live" href="#/">返回首页</a></div></main>${footer()}`}
function serviceChat(){return serviceChats.find(chat=>chat.id===selectedServiceChatId)||serviceChats[0]}
function serviceChatItem(chat){let selected=chat.id===selectedServiceChatId;return `<button class="service-chat-item ${selected?'selected':''}" data-service-chat="${chat.id}" aria-pressed="${selected}"><span class="service-avatar"><img src="${chat.avatar}" alt="${chat.name}"><i class="${chat.status}"></i></span><span class="service-chat-copy"><span class="service-chat-name"><b>${chat.name}</b><time>${chat.time}</time></span><small>${chat.preview}</small></span></button>`}
function serviceMessage(message,chat){return `<article class="service-message ${message.side}"><div class="message-avatar">${message.side==='service'?`<img src="${chat.avatar}" alt="${chat.name}">`:'我'}</div><div class="message-copy"><span class="message-sender">${message.side==='service'?chat.name:'我'} <time>${message.time}</time></span><p>${message.text}</p></div></article>`}
function chatPage(){let chat=serviceChat();return `${header()}<main class="service-chat-page"><section class="service-chat-shell" aria-label="客服聊天"><aside class="service-chat-list"><header><div><h1>聊天</h1></div><span>${serviceChats.length} 条会话</span></header><div class="service-chat-list-scroll">${serviceChats.map(serviceChatItem).join('')}</div></aside><section class="service-chat-detail"><header class="service-chat-detail-head"><span class="service-avatar large"><img src="${chat.avatar}" alt="${chat.name}"><i class="${chat.status}"></i></span><span><h2>${chat.name}</h2><p><i class="${chat.status}"></i>${chat.status==='online'?'在线 · 通常即时回复':'离线 · 工作时间将尽快回复'}</p></span></header><div class="service-message-area" id="serviceMessageArea">${chat.messages.map(message=>serviceMessage(message,chat)).join('')}</div><form class="service-compose" id="serviceChatForm"><div><input id="serviceChatInput" maxlength="300" placeholder="输入消息" autocomplete="off" aria-label="聊天消息"></div><button type="submit" disabled>发送</button></form></section></section></main>`}
function bindServiceChat(){document.querySelectorAll('[data-service-chat]').forEach(button=>button.onclick=()=>{selectedServiceChatId=button.dataset.serviceChat;render()});let input=document.querySelector('#serviceChatInput'),form=document.querySelector('#serviceChatForm'),send=form?.querySelector('button');if(input&&send){let sync=()=>send.disabled=!input.value.trim();input.addEventListener('input',sync);sync()}form?.addEventListener('submit',event=>{event.preventDefault();let text=input.value.trim();if(!text)return;let chat=serviceChat();let now=new Date();chat.messages.push({side:'user',text,time:`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`});chat.preview=text;chat.time='刚刚';render();requestAnimationFrame(()=>{let area=document.querySelector('#serviceMessageArea');if(area)area.scrollTop=area.scrollHeight})});requestAnimationFrame(()=>{let area=document.querySelector('#serviceMessageArea');if(area)area.scrollTop=area.scrollHeight})}
function detailPage(type, id){ return `${header()}<main class="subpage"><div class="detail-card"><div><span class="tag">球队</span><h1>${decodeURIComponent(id)} 球队详情</h1><p>球队 ID：${decodeURIComponent(id)}。后续将在此接入赛程、阵容、新闻与数据。</p><a class="go-live" href="#/matches">查看赛事排行</a></div></div></main>${footer()}`}
function render(){let h=location.hash||'#/'; if(h==='#/'||h==='') app.innerHTML=home(); else if(h==='#/live') app.innerHTML=livePage(); else if(h==='#/schedule') app.innerHTML=schedulePage(); else if(h==='#/matches') app.innerHTML=matchesPage(); else if(h==='#/chat') app.innerHTML=chatPage(); else if(h.startsWith('#/search')) app.innerHTML=searchPage(); else if(h.startsWith('#/profile/')) app.innerHTML=profilePage(h.split('/').pop()); else if(h.startsWith('#/match/')) app.innerHTML=matchDetailPage(h.split('/').pop()); else if(h.startsWith('#/room/'))app.innerHTML=roomPage(h.split('/').pop()); else if(h.startsWith('#/team/'))app.innerHTML=detailPage('team',h.split('/').pop()); else {let map={'#/matches':['赛事','赛事中心与完整球队排行已为后续开发预留。'],'#/chat':['聊天','与球迷一起，聊你所热爱的比赛。']}; app.innerHTML=simplePage(...(map[h]||['页面不存在','请返回首页继续浏览。']));} bind(); }
function bind(){bindServiceChat();document.querySelectorAll('[data-match-sport]').forEach(b=>b.onclick=()=>{matchLeagueFilters[matchSport]=new Set(matchLeagues);matchSport=b.dataset.matchSport;matchLeagues=new Set(matchLeagueFilters[matchSport]||[]);matchFilterOpen=false;render()});document.querySelectorAll('[data-match-tab]').forEach(b=>b.onclick=()=>{matchTab=b.dataset.matchTab;render()});document.querySelectorAll('[data-match-date]').forEach(b=>b.onclick=()=>{matchTab==='schedule'?matchScheduleDate=b.dataset.matchDate:matchResultDate=b.dataset.matchDate;render()});document.querySelector('[data-match-filter]')?.addEventListener('click',()=>{if(matchFilterOpen){matchFilterOpen=false;render();return}matchDraftLeagues=new Set(matchLeagues);matchFilterOpen=true;render()});document.querySelectorAll('[data-match-filter-close]').forEach(b=>b.addEventListener('click',()=>{matchFilterOpen=false;render()}));document.querySelectorAll('[data-match-league]').forEach(b=>b.onclick=()=>{let x=b.dataset.matchLeague;matchDraftLeagues.has(x)?matchDraftLeagues.delete(x):matchDraftLeagues.add(x);refreshMatchDraftUI()});document.querySelectorAll('[data-match-select]').forEach(b=>b.onclick=()=>{let leagues=[...new Set(matchEvents.filter(e=>matchSport==='recommend'||matchType(e)===matchSport).map(e=>e.league))];if(b.dataset.matchSelect==='all')matchDraftLeagues=new Set(leagues);else matchDraftLeagues=new Set(leagues.filter(x=>!matchDraftLeagues.has(x)));refreshMatchDraftUI()});document.querySelectorAll('[data-match-reset]').forEach(b=>b.onclick=()=>{matchDraftLeagues.clear();refreshMatchDraftUI()});document.querySelector('[data-match-confirm]')?.addEventListener('click',()=>{matchLeagues=new Set(matchDraftLeagues);matchLeagueFilters[matchSport]=new Set(matchLeagues);matchFilterOpen=false;render()});
document.querySelectorAll('[data-match-follow]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();let x=b.dataset.matchFollow;followedMatches.has(x)?followedMatches.delete(x):followedMatches.add(x);render()});
document.querySelectorAll('[data-schedule-day]').forEach(button=>button.onclick=()=>{scheduleDay=button.dataset.scheduleDay;render()});document.querySelectorAll('[data-schedule-sport]').forEach(button=>button.onclick=()=>{scheduleSport=button.dataset.scheduleSport;render()});document.querySelectorAll('[data-live-category]').forEach(button=>button.onclick=()=>{liveCategory=button.dataset.liveCategory;document.querySelectorAll('[data-live-category]').forEach(item=>{let selected=item.dataset.liveCategory===liveCategory;item.classList.toggle('selected',selected);item.setAttribute('aria-selected',selected)});let grid=document.querySelector('#liveGrid');if(grid)grid.innerHTML=liveGrid()});document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{activeLive=+b.dataset.channel;render(); window.scrollTo({top:0,behavior:'smooth'})});document.querySelectorAll('[data-football]').forEach(b=>b.onclick=()=>{footballLeague=b.dataset.football;render()});document.querySelectorAll('[data-basketball]').forEach(b=>b.onclick=()=>{basketballLeague=b.dataset.basketball;render()});document.querySelectorAll('[data-conf]').forEach(b=>b.onclick=()=>{nbaConference=b.dataset.conf;render()});document.querySelector('[data-follow-btn]')?.addEventListener('click',button=>{let id=button.currentTarget.dataset.followHost;if(followedHosts.has(id))followedHosts.delete(id);else followedHosts.add(id);render()});document.querySelectorAll('[data-host-follow]').forEach(button=>button.onclick=event=>{event.preventDefault();event.stopPropagation();let host=hostDirectory.find(item=>item.id===button.dataset.hostFollow);if(followedHosts.has(host.id)){followedHosts.delete(host.id);host.fans-=1}else{followedHosts.add(host.id);host.fans+=1}render()});document.querySelectorAll('[data-host-open]').forEach(card=>{let open=()=>{let host=hostDirectory.find(item=>item.id===card.dataset.hostOpen);location.hash=host.liveRoom?`#/room/${host.liveRoom}`:`#/profile/${host.id}`};card.onclick=open;card.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}}});document.querySelector('[data-share]')?.addEventListener('click',()=>{navigator.clipboard?.writeText(location.href).catch(()=>{});showToast('链接复制成功')});document.querySelectorAll('[data-player]').forEach(button=>button.onclick=()=>{let action=button.dataset.player;if(action==='play')playerPlaying=!playerPlaying;if(action==='mute')playerMuted=!playerMuted;if(action==='danmaku')danmakuOn=!danmakuOn;if(action==='quality')qualityOpen=!qualityOpen;if(action==='fullscreen')showToast('已进入全屏模式（原型演示）');render()});document.querySelectorAll('[data-quality]').forEach(button=>button.onclick=()=>{quality=button.dataset.quality;qualityOpen=false;render()});document.querySelector('[data-player-volume]')?.addEventListener('input',event=>{playerMuted=Number(event.target.value)===0;});document.querySelectorAll('[data-side-tab]').forEach(button=>button.onclick=()=>{roomSideTab=button.dataset.sideTab;if(roomSideTab==='chat')selectedGroupId=null;render()});document.querySelectorAll('[data-group]').forEach(button=>button.onclick=()=>{selectedGroupId=button.dataset.group;render()});document.querySelector('[data-back-group]')?.addEventListener('click',()=>{selectedGroupId=null;render()});document.querySelector('#roomChatForm')?.addEventListener('submit',event=>{event.preventDefault();let input=document.querySelector('#roomChatInput'),text=input.value.trim();if(!text)return;chatMessages.push({vip:'VIP 1',badge:'新球迷',name:'我',text});render();setTimeout(()=>{let box=document.querySelector('#chatScroll');if(box)box.scrollTop=box.scrollHeight},0)});document.querySelector('#groupChatForm')?.addEventListener('submit',event=>{event.preventDefault();let input=document.querySelector('#groupChatInput'),text=input.value.trim();if(!text||!selectedGroupId)return;(groupMessages[selectedGroupId]||=[]).push({vip:'VIP 1',badge:'新球迷',name:'我',text});render();setTimeout(()=>{let box=document.querySelector('#groupScroll');if(box)box.scrollTop=box.scrollHeight},0)});document.querySelectorAll('[data-gift-page]').forEach(button=>button.onclick=()=>{giftPage=Math.max(0,Math.min(Math.ceil(gifts.length/8)-1,giftPage+(button.dataset.giftPage==='next'?1:-1)));render()});document.querySelectorAll('[data-gift-send]').forEach(button=>button.onclick=()=>{let gift=gifts.find(item=>item.id===button.dataset.giftSend);showToast(`已赠送${gift.name}`)});document.querySelector('[data-open-gifts]')?.addEventListener('click',()=>showToast('请从左侧礼物栏选择礼物'));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{let a=b.dataset.action;if(a==='game')location.hash='#/game'; else if(a==='app-download'){if(APP_DOWNLOAD_URL)window.open(APP_DOWNLOAD_URL,'_blank','noopener');else showToast('App 下载即将开始（原型演示）')} else if(a==='cast')location.hash='#/creator'; else if(a==='watch')showToast('直播播放功能已就绪（原型演示）'); else if(a==='logout')showToast('已退出登录（原型演示）'); else if(['recharge','bag','noble'].includes(a))showToast({recharge:'充值中心已打开（原型演示）',bag:'背包已打开（原型演示）',noble:'贵族中心已打开（原型演示）'}[a])});let avatar=document.querySelector('#avatarBtn'),menu=document.querySelector('#userMenu');if(avatar)avatar.onclick=e=>{e.stopPropagation();menu.classList.toggle('open')};document.onclick=e=>{if(menu&&!menu.contains(e.target))menu.classList.remove('open');if(matchFilterOpen&&!e.target.closest('.match-filter-popover')&&!e.target.closest('[data-match-filter]')){matchFilterOpen=false;render()}};document.querySelector('#searchForm')?.addEventListener('submit',event=>{event.preventDefault();let q=document.querySelector('#searchInput').value.trim();if(q)location.hash=`#/search?keyword=${encodeURIComponent(q)}`});if(entryVisible&&document.querySelector('.entry-toast'))setTimeout(()=>{entryVisible=false;document.querySelector('.entry-toast')?.remove()},3000)}
window.addEventListener('hashchange',()=>{activeLive=0;render();window.scrollTo({top:0,behavior:'smooth'})});render();
